local ActivityNightCatCardInfoBehaviour = Class('ActivityNightCatCardInfoBehaviour')

--region lifecycle

function ActivityNightCatCardInfoBehaviour:__init()
    self.events = {}
    self.config = {
        cardStatus = {
            NotGet = 0,
            HasReceived = 1
        }
    }
end

function ActivityNightCatCardInfoBehaviour:__delete()
    self.events = nil
end

function ActivityNightCatCardInfoBehaviour:Awake()
    self._status = self.config.cardStatus.NotGet
    ---@type RoleCardCustomizeVo
    self._cardInfoVo = nil
    ---@type GetCardRobotAttributeVo
    self._roleAttributeVo = nil
    SetButtonAction(self.controller.gameObject, Bind(self, self.OnClickHandler))
end

function ActivityNightCatCardInfoBehaviour:Start()

end

function ActivityNightCatCardInfoBehaviour:OnDestroy()
    for k, v in pairs(self.events) do
        Events.RemoveListener(k, v)
    end

    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

