--endregion init

--region handler
function ActivityNightCatCardInfoBehaviour:OnClickHandler()
    if isNull(self._cardInfoVo) then
        return
    end
    CardUtils.ShowCardPreviewById(self._cardInfoVo.effectId, { { id = Constants.UITypeIds.ActivityNightCatDialog } })
end
--endregion handler

--region public
function ActivityNightCatCardInfoBehaviour:Refresh(pageStatus, rewards)
    self:ReloadData(pageStatus, rewards)
end
--endregion public

--region private
function ActivityNightCatCardInfoBehaviour:RefreshUI()
    CfUtils.FillImage(self.ImgCard, self._cardInfoVo.photoId)
    CfUtils.FillText(self.TxtName, self._cardInfoVo.name)

    CfUtils.FillImage(self.HasReceived, self._cardInfoVo.photoId)
    CfUtils.FillText(self.TxtLv, string.format("LV.%d", checkNumber(self._roleAttributeVo.cardLevel)))

    CfUtils.SetUISwitchImage(self.ImgRareIcon, self._roleAttributeVo.advanceLevel)
    CfUtils.SetUISwitchImage(self.ImgRareIconbg, self._roleAttributeVo.advanceLevel)
    CfUtils.SetActive(self.HasReceived, self._status == self.config.cardStatus.HasReceived)
    CfUtils.GetOrAddComponent(self.ImgRareIcon, UIGrayGraphics):MarkGray(self._status == self.config.cardStatus.HasReceived)
    CfUtils.GetOrAddComponent(self.ImgRareIconbg, UIGrayGraphics):MarkGray(self._status == self.config.cardStatus.HasReceived)
end

function ActivityNightCatCardInfoBehaviour:ReloadData(pageStatus, rewards)
    ---@type RoleCardCustomizeVo
    local vo = nil
    for i, reward in ipairs(rewards) do
        local goodsId = reward.goodsId
        local num = reward.num
        local type = GoodsUtils.GetIdType(goodsId)
        if type == Constants.IDType.RoleCardCustomize then
            vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            break
        end
    end
    if isNull(vo) then
        CfUtils.SetActive(self.controller.gameObject, false)
        return
    end

    --- 页面状态为已经领取
    if pageStatus == 3 then
        self._status = self.config.cardStatus.HasReceived
    end

    self._cardInfoVo = vo
    self._roleAttributeVo = CardConfMgr:GetInstance():GetCardRobotAttributeVo(self._cardInfoVo.effectId)

    self:RefreshUI()
end
--endregion private

